INSERT INTO `post` (`id`, `title`, `content`, `createdat`, `category`, `imagePath`) VALUES
(2, 'Aluvihara Rock Cave Temple', '<p><span style=\"font-family: \'times new roman\', times, serif;\"><span style=\"font-size: 14pt;\">Also called Matale Alu Viharaya, this sacred Buddhist temple is located in Aluvihare, Matale District of Sri Lanka. Surrounded by hills, the Aluvihara cave temple is situated 30 km north of Kandy on the Matale-Dambulla road. The history of Aluvihare Rock Temple dates back to the 3rd Century B.C during the reign of King Devanampiyatissa. It is believed that the King built the dagoba, planted the Bo sapling, and founded the temple after the introduction of Buddhism to the country during his reign.</span></span></p>\r\n<p><span style=\"font-family: \'times new roman\', times, serif;\"><span style=\"font-size: 14pt;\">Aluvihare Rock Temple is historically significant as the site where the P?li Canon was first written down completely in text on ola (palm) leaves. Several monastery caves near the temple exhibit frescoes that add to its cultural value.</span></span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<!-- Image Row -->\r\n<div style=\"display: flex; justify-content: space-around; width: 100%; margin-bottom: 50px;\"><!-- Image 1 -->\r\n<div style=\"padding: 5px; transition: transform 0.3s ease, background-color 0.3s ease;\"><img style=\"width: 400px; height: 400px;\" src=\"data:image/jpeg;base64,\" alt=\"Image 1\"></div>\r\n<!-- Image 2 -->\r\n<div style=\"padding: 5px; transition: transform 0.3s ease, background-color 0.3s ease;\"><img style=\"width: 400px; height: 400px;\" src=\"data:image/jpeg;base64,\" alt=\"Image 2\"></div>\r\n<!-- Image 3 -->\r\n<div style=\"padding: 5px; transition: transform 0.3s ease, background-color 0.3s ease;\"><img style=\"width: 400px; height: 400px;\" src=\"data:image/jpeg;base64,\" alt=\"Image 3\"></div>\r\n</div>\r\n<!-- Centered Image Buttons -->\r\n<div style=\"display: flex; flex-direction: row; text-align: center;\"><!-- Location Button -->\r\n<div style=\"margin: 5px;\"><button style=\"border: none; padding: 0; background-color: transparent; transition: transform 0.3s ease, background-color 0.3s ease;\"><a title=\"Go to the Location\" href=\"https://www.google.com/maps/dir/Aluviharaya+Rock+Cave+Temple,+Thotagamuwa//@7.356624,80.5997696,10.5z/data=!4m8!4m7!1m5!1m1!1s0x3afcf5459de99697:0x61d8f01aa0e120b1!2m2!1d80.6217839\" target=\"_blank\" rel=\"noopener\"> <img style=\"width: 100px; height: 100px; transition: transform 0.3s ease;\" src=\"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSYBSqxlL7VIaSFlo-yNVNQbgyfgfQb9y7fYg&amp;s\" alt=\"Location\"></a> </button>\r\n<div>Location</div>\r\n</div>\r\n<!-- Hotels Button -->\r\n<div style=\"margin: 5px;\"><button style=\"border: none; padding: 0; background-color: transparent; transition: transform 0.3s ease, background-color 0.3s ease;\"><a title=\"Go to the Hotels &amp; resturents\" href=\"http://localhost/Travel%20guide%20of%20matale%20district/travel/src/post.php?id=3\"> <img style=\"width: 100px; height: 100px; transition: transform 0.3s ease;\" src=\"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTk66uKADqvsKNhSVJ-B2JGoKwvXhTTYXl63g&amp;s\" alt=\"Hotels\"></a> </button>\r\n<div>Hotels &amp; Resorts</div>\r\n</div>\r\n<!-- Restaurants Button -->\r\n<div style=\"margin: 5px;\"><button style=\"border: none; padding: 0; background-color: transparent; transition: transform 0.3s ease, background-color 0.3s ease;\"><a href=\"http://localhost/Travel%20guide%20of%20matale%20district/travel/src/post.php?id=11\"> <img style=\"width: 100px; height: 100px; transition: transform 0.3s ease;\" src=\"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTPIymQl6uUMPT6VGNyhSp_nD62KXnRq0Yn7w&amp;s\" alt=\"Restaurants\"></a> </button>\r\n<div>Restaurants</div>\r\n</div>\r\n<!-- Hospital Button -->\r\n<div style=\"margin: 5px;\"><button style=\"border: none; padding: 0; background-color: transparent; transition: transform 0.3s ease, background-color 0.3s ease;\"><a title=\"Go to Hospitals\" href=\"http://localhost/Travel%20guide%20of%20matale%20district/travel/src/post.php?id=12\"> <img style=\"width: 100px; height: 100px; transition: transform 0.3s ease;\" src=\"data:image/png;base64,\" alt=\"Hospital\"></a> </button>\r\n<div>Hospital</div>\r\n</div>\r\n<!-- Fuel Station Button -->\r\n<div style=\"margin: 5px;\"><button style=\"border: none; padding: 0; background-color: transparent; transition: transform 0.3s ease, background-color 0.3s ease;\"><a title=\"Go near by feul statoin\" href=\"http://localhost/Travel%20guide%20of%20matale%20district/travel/src/post.php?id=13\"> <img style=\"width: 100px; height: 100px; transition: transform 0.3s ease;\" src=\"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRMIZc1BpBIOnoZSa_t_usoC6bq6HMYGk_MIg&amp;s\" alt=\"Fuel Station\"></a> </button>\r\n<div>Fuel Stations</div>\r\n</div>\r\n<!-- Wine Bar Button -->\r\n<div style=\"margin: 5px;\"><button style=\"border: none; padding: 0; background-color: transparent; transition: transform 0.3s ease, background-color 0.3s ease;\"><a title=\"Go near by wine store\" href=\"http://localhost/Travel%20guide%20of%20matale%20district/travel/src/post.php?id=14\"> <img style=\"width: 100px; height: 100px; transition: transform 0.3s ease;\" src=\"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR0uyOYz_2vT9zAq5sX51kyiBx4FDOgHywH5A&amp;s\" alt=\"Wine Bar\"></a> </button>\r\n<div>Wine Bars</div>\r\n</div>\r\n</div>', '2024-09-18 14:42:15', 'Places', '../images/a1.jpeg');
INSERT INTO `post` (`id`, `title`, `content`, `createdat`, `category`, `imagePath`) VALUES
(3, 'Hotels&Resorts Near By Aluvihara Rock Cave Temple', '<div style=\"width: 100%; max-width: 800px; height: 600px; border: 2px solid green; border-radius: 20px; padding: 20px; position: relative;\"><!-- Topic Heading -->\r\n<div style=\"text-align: center; font-size: 24px; font-weight: bold; margin-bottom: 20px;\">Welcome to Siyonra Bungalow Hotel</div>\r\n<div style=\"display: flex; justify-content: space-between; margin-bottom: 20px;\">\r\n<div style=\"width: 200px; height: 200px; border: 2px solid green; border-radius: 20px; overflow: hidden;\"><img style=\"width: 100%; height: 100%; object-fit: cover;\" src=\"data:image/jpeg;base64,\" alt=\"Image 1\"></div>\r\n<div style=\"width: 200px; height: 200px; border: 2px solid green; border-radius: 20px; overflow: hidden;\"><img style=\"width: 100%; height: 100%; object-fit: cover;\" src=\"data:image/jpeg;base64,\" alt=\"Image 2\"></div>\r\n<div style=\"width: 200px; height: 200px; border: 2px solid green; border-radius: 20px; overflow: hidden;\"><img style=\"width: 100%; height: 100%; object-fit: cover;\" src=\"data:image/jpeg;base64,\" alt=\"Image 3\"></div>\r\n</div>\r\n<div style=\"margin-bottom: 20px;\">\r\n<p>Located in Matale, 19 miles from Kandy City Center Shopping Mall, Siyonra Bungalow has accommodations with an outdoor swimming pool, free private parking, a garden and a terrace. Among the facilities of this property are a restaurant, room service and a 24-hour front desk, along with free WiFi throughout the property. The hotel has family rooms. The rooms in the hotel are equipped with a TV. Featuring a private bathroom with a shower and a hairdryer, certain accommodations at Siyonra Bungalow also feature a mountain view. At the accommodation rooms contain bed linen and towels.</p>\r\n</div>\r\n<div style=\"position: absolute; bottom: 20px; left: 20px; width: 50px; height: 50px; border: 2px solid green; border-radius: 50%; overflow: hidden; cursor: pointer;\"><a title=\"Go Map\" href=\"https://www.google.com/maps/place/Siyonra/@7.512474,80.6132991,17z/data=!3m1!4b1!4m10!3m9!1s0x3ae34f24c3ca7b2d:0xc3e2c751bde3bb2e!5m3!1s2024-09-19!4m1!1i2!8m2!3d7.512474!4d80.61817!16s%2Fg%2F11l6t3sl9l?entry=ttu&amp;g_ep=EgoyMDI0MDkxNi4wIKXMDSoASAFQAw%3D%3D\" target=\"_blank\" rel=\"noopener\"><img style=\"width: 100%; height: 100%; object-fit: cover;\" src=\"data:image/png;base64,\" alt=\"Image icon\"></a></div>\r\n<div style=\"position: absolute; bottom: 20px; right: 20px; border: 2px solid green; border-radius: 10px; padding: 5px;\">TP: 0742782746</div>\r\n</div>\r\n<div style=\"width: 100%; max-width: 800px; display: flex; justify-content: space-between; margin-top: 20px;\"><!-- Back Button --> <button style=\"padding: 0; border: none; border-radius: 10px; background-color: white; cursor: pointer; display: flex; align-items: center; justify-content: center; width: 100px; height: 50px; overflow: hidden;\"> <a title=\"Back\" href=\"http://localhost/Travel%20guide%20of%20matale%20district/travel/src/post.php?id=2\"><img style=\"width: 100%; height: 100%; object-fit: cover;\" src=\"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSPwyGnASWnXaxLJBI5yiFoJMx61DhCr5Klnw&amp;s\" alt=\"Back\"></a> </button> <!-- Next Button --> <button style=\"padding: 0; border: none; border-radius: 10px; background-color: white; cursor: pointer; display: flex; align-items: center; justify-content: center; width: 100px; height: 50px; overflow: hidden;\"> <a title=\"Next page\" href=\"http://localhost/Travel%20guide%20of%20matale%20district/travel/src/post.php?id=9\"><img style=\"width: 100%; height: 100%; object-fit: cover;\" src=\"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcShqpjOf53tAU8T4-k80nKQ1ZflUcLvZJPXtA&amp;s\" alt=\"Next\"> </a></button></div>', '2024-09-18 16:46:46', 'Hotels ', 'Untitled-2.jpg');
